"""Styles for the local living-brand workshop."""

# Static CSS is kept as one dependency-free asset.
# ruff: noqa: E501

WORKSHOP_CSS = """
:root{--paper:#f4f0e7;--surface:#fffdf7;--ink:#17201c;--muted:#526058;--accent:#b83b27;--line:#aaa99f}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:1rem/1.55 system-ui,sans-serif}header,main{width:min(72rem,calc(100% - 2rem));margin:auto}header{display:flex;justify-content:space-between;padding:1.25rem 0;border-bottom:1px solid var(--line)}nav{display:flex;gap:1rem}a{color:inherit;text-underline-offset:.2em}.skip-link{position:fixed;transform:translateY(-200%);background:var(--ink);color:white;padding:.75rem}.skip-link:focus{transform:none}main{padding:3rem 0}.intro{max-width:44rem}.eyebrow{text-transform:uppercase;font-weight:800;letter-spacing:.12em;color:var(--accent)}h1{font:500 clamp(2.5rem,7vw,5rem)/1 Georgia,serif}form{display:grid;gap:.75rem;padding:1.5rem;background:var(--surface);border:2px solid var(--ink)}input,textarea,select,button{font:inherit;padding:.75rem;border:2px solid var(--ink);background:var(--surface);color:var(--ink)}button{cursor:pointer;background:var(--accent);color:white;font-weight:800}.workspace-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}.workspace-card{padding:1rem;background:var(--surface);border:1px solid var(--line)}.workshop-grid{display:grid;grid-template-columns:18rem 1fr;gap:2rem}#section-navigation{display:grid;align-content:start}#section-navigation button{text-align:left;background:var(--surface);color:var(--ink)}.block-editor{display:grid;gap:.35rem}textarea{min-height:8rem;resize:vertical}:focus-visible{outline:3px solid var(--accent);outline-offset:3px}@media (max-width: 48rem){header,.workshop-grid{display:grid;grid-template-columns:1fr}.workspace-grid{grid-template-columns:1fr}#section-navigation{position:static}}@media (prefers-reduced-motion: reduce){*{scroll-behavior:auto!important;transition:none!important}}
"""
